<script setup>

import AuthenticatedLayout from "@/Layouts/AuthenticatedLayout.vue";
import {computed, nextTick, onMounted, ref, watch} from "vue";
import Pagination from "@/Components/Pagination.vue";
import {router, usePage} from "@inertiajs/vue3";
import debounce from 'lodash.debounce'
import DialogCreateHackathon from '@/Components/Dialog/CreateHackathon.vue'

const props = defineProps({
    user: Object,
    can: Object,
    upcomingHackathons: Object,
    pastHackathons: Object,
    query: Object,
})

const search    = ref(usePage().props.query?.q     ?? '')
const sort      = ref(usePage().props.query?.order ?? 'dateA')

const activeTab = ref(usePage().props.query?.tab   === 'past' ? 1 : 0)

function setActiveTab(idx) {
    if (activeTab.value === idx) return
    activeTab.value = idx
    fetchHackathons(1)
}

const hackathons = computed(() => {
    return activeTab.value === 0
        ? props.upcomingHackathons
        : props.pastHackathons
})

function go(pageUrl) {
    // pageUrl уже содержит ?page=N + твои q/filters благодаря withQueryString()
    router.get(pageUrl, {}, { preserveState:true, preserveScroll:true, replace:true })
}

const buildQuery = (page = 1) => ({
    q     : search.value      || undefined,
    order : sort.value        || undefined,
    tab   : activeTab.value===0 ? 'upcoming' : 'past',
    page  : page
})

const fetchHackathons = debounce((page = 1) => {
    router.get(
        route('my-hackathons'),
        buildQuery(page),
        { preserveState: true, preserveScroll: true, replace: true }
    )
}, 400)

watch([sort], () => fetchHackathons(1))

const tabsRef = ref([]);
const sliderStyle = computed(() => {
    if (!tabsRef.value.length) return {};

    const activeTabElement = tabsRef.value[activeTab.value];
    const left = activeTabElement?.offsetLeft || 0;
    const width = activeTabElement?.offsetWidth || 0;

    return {
        left: `${left}px`,
        width: `${width}px`,
    };
});

function formatDate(dateStr) {
    const date = new Date(dateStr)
    const day = String(date.getDate()).padStart(2, '0')
    const month = String(date.getMonth() + 1).padStart(2, '0')
    const year = date.getFullYear()
    return `${day}.${month}.${year}`
}

const showDialog = ref(false)

onMounted(async () => {
    await nextTick(() => {
        tabsRef.value = document.querySelectorAll('.my-hackathon__tabs_item');
    });
});
</script>

